// Catálogo de productos Hotmart para animales
const PRODUCTOS = [
  { id: 'dieta-natural',   nombre: 'Dieta Natural para Perros y Gatos',         link: 'https://go.hotmart.com/X103617747C',    imagen: 'https://static-media.hotmart.com/KNdDfZogqE2CWDv4nqEsswzDFjc=/300x300/filters:quality(100)/hotmart/product_pictures/ecbf6914-08bb-4682-aa5b-1990b80b5afb/postinstagrampatitas.png',  tipo: 'Guía',    keywords: ['dieta','alimentacion','comida','nutricion','natural'] },
  { id: 'snack-barf',     nombre: 'Snack BARF en Minutos',                     link: 'https://go.hotmart.com/R103617833Q',    imagen: 'https://static-media.hotmart.com/XusqQYSq_oAB8-EO0Iwr3xVnPMk=/300x300/smart/filters:format(webp):background_color(white)/hotmart/product_pictures/aaef333c-c030-4c46-a0e7-0c1b780837fe/snackbarf600x600.png?w=920', tipo: 'Recetas', keywords: ['barf','snack','receta','premio'] },
  { id: 'adiestramiento', nombre: 'Adiestramiento Canino Profesional',         link: 'https://go.hotmart.com/D104257979A',    imagen: 'https://hotmart.s3.amazonaws.com/product_pictures/141a3c3d-a535-40f5-99e1-a275199b7e98/Portadahotmart5.png',  tipo: 'Curso',   keywords: ['adiestrar','entrenamiento','conducta','perro','obediencia'] },
  { id: 'entiende-gato',  nombre: 'Entiende a tu Gato: Guía Práctica',        link: 'https://go.hotmart.com/F104226854F',    imagen: 'https://d1yei2z3i6k35z.cloudfront.net/11998843/683bb259ca94a_CopiadeSint%C3%ADtulo1.png', tipo: 'Guía',    keywords: ['gato','felino','comportamiento gato'] },
  { id: 'mascotas-sanas', nombre: 'Mascotas Sanas',                            link: 'https://go.hotmart.com/L104257678P?dp=1', imagen: 'https://static-media.hotmart.com/9H3NJb3S4H61OsufTjZpXLy-8KY=/300x300/smart/filters:format(webp):background_color(white)/hotmart/product_pictures/78592f13-96f1-4724-9b6a-2640aadcf606/MasterSello20211116T162945331.jpg?w=920', tipo: 'Curso', keywords: ['salud','veterinario','enfermedad','sano'] },
  { id: 'vital-pet',      nombre: 'Vital Pet System',                          link: 'https://go.hotmart.com/W104257847B',    imagen: 'https://static-media.hotmart.com/F3PzytJIAVCectZMFSnvMHJFV5g=/filters:background_color(white)/hotmart/product_pictures/a801721c-590d-4a30-ab01-5fe5eb532e8f/PORTADAVITALPET.png', tipo: 'Sistema', keywords: ['cocido','casero','sistema','vital'] }
];

const body = $input.item.json.body || $input.item.json;
const titulo    = (body.title || '').toLowerCase();
const contenido = (body.content || '').toLowerCase();

// Detectar nicho
const palabrasLeyes = ['ley','derecho','abogado','legal','contrato','juicio','tribunal','herencia','divorcio','laboral'];
const esLeyes = palabrasLeyes.some(p => titulo.includes(p) || contenido.includes(p));

// Seleccionar mejor producto para animales por relevancia de keywords
let productoSeleccionado = PRODUCTOS[0];
let mejorScore = -1;
if (!esLeyes) {
  for (const p of PRODUCTOS) {
    const score = p.keywords.filter(kw => titulo.includes(kw) || contenido.includes(kw)).length;
    if (score > mejorScore) { mejorScore = score; productoSeleccionado = p; }
  }
}

return [{
  json: {
    blogId:   body.blogId,
    postId:   body.postId,
    titulo:   body.title,
    contenido: body.content,
    nicho:    esLeyes ? 'leyes' : 'animales',
    producto: esLeyes ? null : productoSeleccionado
  }
}];
